    faq: { title: "FAQ", subtitle: "Hai una domanda? La risposta Ã¨ probabilmente qui.", back: "â† Indietro", noAnswerTitle: "Non hai trovato la risposta?", noAnswerSubtitle: "Inviaci un'email e risponderemo prima possibile.", questions: [
      { q: "Devo caricare le mie foto da qualche parte?", a: "No. Le tue foto rimangono esattamente dove sono, nel tuo Google Drive. PhotoDrive le legge da lÃ¬ e le mostra al tuo cliente. Non devi fare nulla di nuovo." },
      { q: "Come vede la galleria il mio cliente?", a: "Una volta creata una galleria, PhotoDrive genera automaticamente un link unico. Lo invii al cliente via email o SMS. Il cliente apre il link e vede la galleria immediatamente, senza registrazione, senza account." },
      { q: "Posso aggiungere una password alla galleria?", a: "SÃ¬. Durante la creazione di una galleria puoi impostare una password. Il cliente dovrÃ  inserirla prima di vedere le foto. La password viene conservata in modo criptato." },
      { q: "Il mio cliente ha bisogno di un account Google?", a: "No. Il tuo cliente non ha bisogno di nessun account. Apre semplicemente il link che gli hai inviato e vede la galleria. Se c'Ã¨ una password, deve solo inserirla." },
      { q: "Il mio cliente puÃ² scaricare le foto?", a: "SÃ¬. Il cliente puÃ² scaricare le singole foto in piena risoluzione o piÃ¹ foto come file ZIP." },
      { q: "Cosa succede se aggiungo o rimuovo foto da Google Drive?", a: "La galleria si aggiorna automaticamente. Le foto che aggiungi appariranno nella galleria, quelle rimosse scompariranno. Non devi fare nulla in PhotoDrive." },
      { q: "Quante gallerie posso creare?", a: "Illimitate. Il tuo abbonamento non ha limiti sul numero di gallerie o foto." },
      { q: "Quali tipi di file sono supportati?", a: "PhotoDrive supporta tutti i formati immagine comuni (JPEG, PNG, WebP, HEIC, ecc.) e video (MP4, MOV, ecc.)." },
      { q: "Le mie foto sono al sicuro?", a: "PhotoDrive ha esclusivamente accesso in sola lettura alla cartella Drive che scegli. Non salviamo le tue foto da nessuna parte. Non modifichiamo nÃ© eliminiamo nulla nel tuo Drive." },
      { q: "Cosa succede se la cartella Drive non Ã¨ pubblica?", a: 'La cartella Drive deve essere impostata in modo che "Chiunque abbia il link" possa visualizzarla. Questo non significa che la cartella appaia su Google.' },
      { q: "Su quali dispositivi funziona PhotoDrive?", a: "PhotoDrive funziona su qualsiasi browser moderno, Chrome, Safari, Firefox, Edge, su desktop, tablet e mobile." },
    ]},
